int pfring_fb_export_json(pfring_flow_balancer *fb, const char *path) {
  char *json;
  FILE *out;

  if(fb == NULL || path == NULL)
    return PFRING_FB_EINVAL;

  json = pfring_fb_stats_json(fb);
  if(json == NULL)
    return PFRING_FB_ENOMEM;

  if(strcmp(path, "-") == 0) {
    fputs(json, stdout);
    free(json);
    return PFRING_FB_OK;
  }

  out = fopen(path, "w");
  if(out == NULL) {
    free(json);
    return PFRING_FB_EINVAL;
  }

  fputs(json, out);
  if(fclose(out) != 0) {
    free(json);
    return PFRING_FB_EINVAL;
  }

  free(json);
  return PFRING_FB_OK;
}

