  key->dst_addr[2] = 0;
  key->dst_addr[3] = 1;
  key->src_port = 1024 + (flow_id % 60000);
  key->dst_port = (x & 1) ? 443 : 53;
  pfring_fb_key_canonicalize(key);
}

