raw_content:
Now I'll refactor this function using apply_patch. I'll replace the whole `pfring_fb_key_parse` (lines 306-356) with:
- helper `fb_ethertype_is_ip()` / dispatchable
- helper `fb_parse_ethertype()` (VLAN loop + L3)
- helper `fb_parse_ethernet()`
- helper `fb_parse_sll(v2)`
- `pfring_fb_key_parse_linktype()`
- `pfring_fb_key_parse()` → AUTO.

I need to be careful that the existing Ethernet behavior is preserved EXACTLY for the normal path. Let me write the replacement.

Let me define linktype constants in the header too. I'll add them near the top defines.

Let me write the C patch. I'll replace from `int pfring_fb_key_parse(const uint8_t *packet, size_t packet_len,\n                        pfring_fb_key *key) {` through the closing brace before `static uint32_t fb_normalize_cpu`.

Let me construct the new code:

```c
static int fb_ethertype_parses_l3(uint16_t ethertype) {
  return ethertype == ETHERTYPE_IP || ethertype == ETHERTYPE_IPV6
    || ethertype == ETHERTYPE_VLAN || ethertype == 0x88a8 /* QinQ */;
}

/*
 * Handle an EtherType at l3_ethertype_offset... Actually we pass the initial
 * ethertype and the offset where its payload (and any 802.1Q tags) begins.
 */
static int fb_parse_ethertype(pfring_fb_key *key, const uint8_t *pkt,
                              size_t len, size_t offset,
                              uint16_t ethertype) {
  while(ethertype == ETHERTYPE_VLAN || ethertype == 0x88a8 /* QinQ */) {
    if(!fb_have_bytes(offset, 4, len))
      return PFRING_FB_EINVAL;
    key->vlan = fb_load_be16(pkt + offset) & 0x0fff;
    ethertype = fb_load_be16(pkt + offset + 2);
    offset += 4;
  }

  key->ethertype = ethertype;

  if(ethertype == ETHERTYPE_IP)
    return fb_parse_ipv4(key, pkt, len, offset);
  if(ethertype == ETHERTYPE_IPV6)
    return fb_parse_ipv6(key, pkt, len, offset);

  return PFRING_FB_OK;
}

static int fb_parse_ethernet(pfring_fb_key *key, const uint8_t *pkt,
                             size_t len) {
  uint16_t ethertype;

  if(!fb_have_bytes(0, 14, len))
    return PFRING_FB_EINVAL;

  memcpy(key->dst_mac, pkt, 6);
  memcpy(key->src_mac, pkt + 6, 6);
  ethertype = fb_load_be16(pkt + 12);

  return fb_parse_ethertype(key, pkt, len, 14, ethertype);
}

/*
 * Linux cooked capture. v1 is 16 bytes (protocol at offset 14, address at 6);
 * v2 is 20 bytes (protocol at offset 0, address at 12). Only the source
 * hardware address is present, so dst_mac stays zeroed.
 */
static int fb_parse_sll(pfring_fb_key *key, const uint8_t *pkt, size_t len,
                        int v2) {
  uint16_t ethertype;
  uint8_t addr_len;
  size_t addr_offset;
  size_t l3_offset;

  if(v2) {
    if(!fb_have_bytes(0, 20, len))
      return PFRING_FB_EINVAL;
    ethertype = fb_load_be16(pkt + 0);
    addr_len = pkt[11];
    addr_offset = 12;
    l3_offset = 20;
  } else {
    if(!fb_have_bytes(0, 16, len))
      return PFRING_FB_EINVAL;
    ethertype = fb_load_be16(pkt + 14);
    addr_len = pkt[5];
    addr_offset = 6;
    l3_offset = 16;
  }

  if(addr_len > 6)
    addr_len = 6;
  if(addr_len > 0 && fb_have_bytes(addr_offset, addr_len, len))
    memcpy(key->src_mac, pkt + addr_offset, addr_len);

  return fb_parse_ethertype(key, pkt, len, l3_offset, ethertype);
}

int pfring_fb_key_parse_linktype(const uint8_t *packet, size_t packet_len,
                                 int linktype, pfring_fb_key *key) {
  int rc;

  if(packet == NULL || key == NULL || packet_len == 0)
    return PFRING_FB_EINVAL;

  memset(key, 0, sizeof(*key));

  switch(linktype) {
  case PFRING_FB_LINK_ETHERNET:
    rc = fb_parse_ethernet(key, packet, packet_len);
    break;

  case PFRING_FB_LINK_LINUX_SLL:
    rc = fb_parse_sll(key, packet, packet_len, 0);
    break;

  case PFRING_FB_LINK_LINUX_SLL2:
    rc = fb_parse_sll(key, packet, packet_len, 1);
    break;

  case PFRING_FB_LINK_RAW:
  case 12 /* DLT_RAW on some platforms */:
    if((packet[0] >> 4) == 6)
      rc = fb_parse_ipv6(key, packet, packet_len, 0);
    else
      rc = fb_parse_ipv4(key, packet, packet_len, 0);
    if(rc == PFRING_FB_OK)
      key->ethertype = (packet[0] >> 4) == 6 ? ETHERTYPE_IPV6
                                             : ETHERTYPE_IP;
    break;

  case PFRING_FB_LINK_AUTO:
  default: {
    uint16_t eth_ethertype = 0;

    /* Raw IP is the common link-less input; keep version-nibble detection. */
    if((packet[0] >> 4) == 4 || (packet[0] >> 4) == 6) {
      int raw_rc;

      key->ethertype = (packet[0] >> 4) == 6 ? ETHERTYPE_IPV6
                                             : ETHERTYPE_IP;
      if((packet[0] >> 4) == 4)
        raw_rc = fb_parse_ipv4(key, packet, packet_len, 0);
      else
        raw_rc = fb_parse_ipv6(key, packet, packet_len, 0);

      if(raw_rc == PFRING_FB_OK) {
        pfring_fb_key_canonicalize(key);
        return PFRING_FB_OK;
      }
      /* Not actually IP (e.g. an Ethernet dst MAC): retry with L2 framing. */
      memset(key, 0, sizeof(*key));
    }

    if(fb_have_bytes(0, 14, packet_len))
      eth_ethertype = fb_load_be16(packet + 12);

    /*
     * Only divert to cooked capture when the Ethernet EtherType slot is not a
     * normal L3/EtherType and the SLL header signature is unambiguous. This
     * keeps every well-formed Ethernet/raw input on its original fast path.
     */
    if(!fb_ethertype_parses_l3(eth_ethertype)) {
      /* SLL2: protocol at 0, reserved MBZ at 2, halen at 11 (<= 8). */
      if(fb_have_bytes(0, 20, packet_len)
         && fb_ethertype_parses_l3(fb_load_be16(packet + 0))
         && fb_load_be16(packet + 2) == 0
         && packet[11] <= 8) {
        rc = fb_parse_sll(key, packet, packet_len, 1);
        if(rc == PFRING_FB_OK) {
          pfring_fb_key_canonicalize(key);
          return PFRING_FB_OK;
        }
        memset(key, 0, sizeof(*key));
      }

      /* SLL v1: address length byte at 5 (<= 8), protocol at 14. */
      if(fb_have_bytes(0, 16, packet_len)
         && packet[4] == 0 && packet[5] <= 8
         && fb_ethertype_parses_l3(fb_load_be16(packet + 14))) {
        rc = fb_parse_sll(key, packet, packet_len, 0);
        if(rc == PFRING_FB_OK) {
          pfring_fb_key_canonicalize(key);
          return PFRING_FB_OK;
        }
        memset(key, 0, sizeof(*key));
      }
    }

    rc = fb_parse_ethernet(key, packet, packet_len);
    break;
  }
  }

  if(rc == PFRING_FB_OK)
    pfring_fb_key_canonicalize(key);

  return rc;
}

int pfring_fb_key_parse(const uint8_t *packet, size_t packet_len,
                        pfring_fb_key *key) {
  return pfring_fb_key_parse_linktype(packet, packet_len,
                                      PFRING_FB_LINK_AUTO, key);
}
```

Wait — there's a subtle issue with the RAW explicit case: I set key->ethertype only after parse and based on nibble; but if nibble isn't 4/6 (caller explicitly says RAW but packet isn't IP), I default to parse_ipv4 which returns EINVAL for too-short/bad. Fine. But the ethertype assignment expression `(packet[0] >> 4) == 6 ? IPV6 : IP` is fine.

Another subtlety: In the original raw branch, it set `key->ethertype` BEFORE parse and ignored parse errors, then canonicalized and returned OK. My AUTO raw path returns OK only if parse succeeds; otherwise falls through. For the EXPLICIT RAW linktype, I return rc (could be EINVAL) and only set ethertype on success; canonicalize only if OK (at bottom `if(rc==OK) canon`). That's reasonable.

But wait, in `pfring_fb_key_parse_linktype` after the switch, `if(rc == OK) canonicalize; return rc;`. For AUTO success paths I early-return after canonicalize (so no double canonicalize — double canonicalize is idempotent anyway because after first canonicalization the endpoints are sorted; canonicalizing again won't swap; hash recomputed same. Actually canonicalize sets key->hash; calling twice is harmless). But I early-return to avoid the bottom. Fine. For AUTO final `rc = fb_parse_ethernet(...)` then break → bottom canonicalize if OK. Good.

Now, one concern: the ORIGINAL Ethernet path returned `PFRING_FB_EINVAL` directly when VLAN truncated or IPv4 parse failed, WITHOUT canonicalize. My fb_parse_ethertype returns EINVAL and fb_parse_ethernet returns it; the bottom `if(rc==OK)` skips canonicalize and we return EINVAL. Same behavior. Good. Original for IPv6 parse failure returned EINVAL too. Preserved.

Original raw path ALWAYS returned OK even on parse failure. My AUTO changes that to fall-through; as discussed strictly better and won't affect valid raw. But could it affect the existing leftover test? The raw `rev` packet: 40 bytes? Let me re-examine: in /tmp/test_fb_parse.c, `uint8_t rev[40]; memcpy(rev,ip,40);` where ip=pkt+14 and the IPv4 total... they built pkt with put16(pkt+16,40) total length 40? Wait they set `put16(pkt+16,40)` — but pkt+14 is IP header start, so pkt+16 is IP byte2 (total length) = 40. IHL: pkt[14]=0x45 → ihl 20. They call parse(rev,28,&b) with len=28 (!) though rev is 40 bytes buffer but pass 28. fb_parse_ipv4: have_bytes(0,20,28) yes; ihl=20 and have_bytes(0,20,28) yes; then l4 ports at offset20 need 4 bytes: have_bytes(20,4,28) yes (8 remaining). OK returns. Good, raw_rc=OK → early return. 

Now the explicit linktype constants. Add to header near other #defines:
```
/* Capture link framing for pfring_fb_key_parse_linktype(). */
#define PFRING_FB_LINK_AUTO 0
#define PFRING_FB_LINK_ETHERNET 1      /* DLT_EN10MB */
#define PFRING_FB_LINK_RAW 101         /* LINKTYPE_RAW / raw IP */
#define PFRING_FB_LINK_LINUX_SLL 113   /* DLT_LINUX_SLL */
#define PFRING_FB_LINK_LINUX_SLL2 276  /* DLT_LINUX_SLL2 */
```
And declare:
```
int pfring_fb_key_parse_linktype(const uint8_t *packet, size_t packet_len,
                                 int linktype, pfring_fb_key *key);
```
right after pfring_fb_key_parse declaration, updating the comment.

Now, `ETHERTYPE_VLAN` and `ETHERTYPE_IPV6` and `ETHERTYPE_IP` come from `<net/ethernet.h>` / `<netinet/...>`? The original code already uses ETHERTYPE_IP, ETHERTYPE_IPV6, ETHERTYPE_VLAN and compiles, so all available. Good. `0x88a8` used directly already.

One more: in fb_parse_sll for v1, `addr_len = pkt[5]` (sll_halen is at offset 4 as a 16-bit big-endian? Actually struct sll_header: sll_halen is `u_int16_t` at offset 4? Let me double check the layout. From linux/if_packet.h / pcap:

```
#define SLL_HDR_LEN	16
struct sll_header {
	u_int16_t sll_pkttype;	/* 0-1 */
	u_int16_t sll_hatype;	/* 2-3 */
	u_int16_t sll_halen;	/* 4-5 */
	u_int8_t  sll_addr[8];	/* 6-13 */
	u_int16_t sll_protocol;	/* 14-15 */
