#include "pfring_flow_balance.h"
#include <arpa/inet.h>
#include <assert.h>
#include <stdio.h>
#include <string.h>

static void w16(uint8_t*p,uint16_t v){uint16_t n=htons(v);memcpy(p,&n,2);}
static void w32(uint8_t*p,uint32_t v){uint32_t n=htonl(v);memcpy(p,&n,4);}

/* Write a minimal IPv4/UDP packet (20 IP + 8 UDP) at ip; returns L3 total. */
static void build_ipv4_udp(uint8_t *ip){
  memset(ip,0,28);
  ip[0]=0x45; ip[1]=0; w16(ip+2,28); w16(ip+4,0x1234);
  w16(ip+6,0); ip[8]=64; ip[9]=17; w16(ip+10,0);
  w32(ip+12,0x0a000001); w32(ip+16,0xc0a80001);
  w16(ip+20,12345); w16(ip+22,53); w16(ip+24,8); w16(ip+26,0);
}
static void build_ipv6_udp(uint8_t *ip){
  memset(ip,0,48);
  ip[0]=0x60; ip[6]=17; ip[7]=64;
  /* src 2001:db8::1, dst 2001:db8::2 */
  ip[8]=0x20;ip[9]=0x01;ip[10]=0x0d;ip[11]=0xb8; ip[23]=1;
  ip[24]=0x20;ip[25]=0x01;ip[26]=0x0d;ip[27]=0xb8; ip[39]=2;
  w16(ip+40,4444); w16(ip+42,53); w16(ip+44,8);
}

int main(void){
  pfring_fb_key k, k2;
  uint8_t buf[128];

  /* 1) plain Ethernet IPv4 UDP */
  memset(buf,0,sizeof buf);
  /* dst 00:11:22:33:44:55 src 66:77:88:99:aa:bb */
  for(int i=0;i<6;i++){buf[i]=0x11*i; buf[6+i]=0x66+0x11*i;}
  w16(buf+12,0x0800); build_ipv4_udp(buf+14);
  assert(pfring_fb_key_parse(buf,14+28,&k)==0);
  assert(k.ip_version==4 && k.protocol==17);
  assert(k.src_port==12345 && k.dst_port==53);
  assert(pfring_fb_key_parse_linktype(buf,14+28,PFRING_FB_LINK_ETHERNET,&k2)==0);
  assert(pfring_fb_key_equal(&k,&k2));

  /* 2) VLAN 802.1Q: eth(14)+tag(4)+ip */
  memset(buf,0,sizeof buf);
  w16(buf+12,0x8100); w16(buf+14,0x007b /*vlan 123*/); w16(buf+16,0x0800);
  build_ipv4_udp(buf+18);
  assert(pfring_fb_key_parse(buf,18+28,&k)==0);
  assert(k.vlan==123 && k.ip_version==4 && k.src_port==12345);

  /* 3) IPv6 UDP over Ethernet */
  memset(buf,0,sizeof buf);
  w16(buf+12,0x86dd); build_ipv6_udp(buf+14);
  assert(pfring_fb_key_parse(buf,14+48,&k)==0);
  assert(k.ip_version==6 && k.protocol==17 && k.src_port==4444 && k.dst_port==53);

  /* 4) SLL v1: 16-byte cooked header + IP */
  memset(buf,0,sizeof buf);
  w16(buf+0,0);          /* pkttype */
  w16(buf+2,1);          /* hatype ARPHRD_ETHER */
  buf[4]=0; buf[5]=6;    /* halen = 6 (00 06) */
  buf[6]=0xde;buf[7]=0xad;buf[8]=0xbe;buf[9]=0xef;buf[10]=0;buf[11]=1;
  w16(buf+14,0x0800);    /* protocol */
  build_ipv4_udp(buf+16);
  size_t sll_len=16+28;
  assert(pfring_fb_key_parse_linktype(buf,sll_len,PFRING_FB_LINK_LINUX_SLL,&k)==0);
  assert(k.ip_version==4 && k.protocol==17 && k.src_port==12345 && k.dst_port==53);
  assert(k.src_mac[0]==0xde && k.src_mac[2]==0xbe);
  assert(pfring_fb_key_parse(buf,sll_len,&k2)==0 && "AUTO sll1");
  assert(k2.ip_version==4 && pfring_fb_key_equal(&k,&k2));

  /* 5) SLL2: 20-byte header + IP */
  memset(buf,0,sizeof buf);
  w16(buf+0,0x0800);     /* protocol */
  w16(buf+2,0);          /* reserved MBZ */
  w32(buf+4,7);          /* ifindex */
  w16(buf+8,1);          /* hatype */
  buf[10]=0;             /* pkttype */
  buf[11]=6;             /* halen */
  buf[12]=0xca;buf[13]=0xfe;buf[14]=0xba;buf[15]=0xbe;buf[16]=0;buf[17]=2;
  build_ipv4_udp(buf+20);
  size_t sll2_len=20+28;
  assert(pfring_fb_key_parse_linktype(buf,sll2_len,PFRING_FB_LINK_LINUX_SLL2,&k)==0);
  assert(k.ip_version==4 && k.src_port==12345);
  assert(k.src_mac[0]==0xca && k.src_mac[1]==0xfe);
  assert(pfring_fb_key_parse(buf,sll2_len,&k2)==0 && "AUTO sll2");
  assert(k2.ip_version==4 && pfring_fb_key_equal(&k,&k2));

  /* 6) Ethernet with 08:00:27 dst MAC must NOT be misread as SLL2 */
  memset(buf,0,sizeof buf);
  buf[0]=0x08; buf[1]=0x00; buf[2]=0x27; /* p[2..3]!=0 so SLL2 guard fails */
  w16(buf+12,0x0800); build_ipv4_udp(buf+14);
  assert(pfring_fb_key_parse(buf,14+28,&k)==0);
  assert(k.ip_version==4 && k.src_port==12345 && k.dst_port==53);

  /* 7) truncated inputs return error, not crash */
  assert(pfring_fb_key_parse(buf,4,&k)!=0);
  assert(pfring_fb_key_parse_linktype(buf,10,PFRING_FB_LINK_LINUX_SLL2,&k)!=0);
  assert(pfring_fb_key_parse(NULL,10,&k)!=0);

  printf("PARSE_LINK_TESTS_OK\n");
  return 0;
}
